"""Glossary lookup for Early Earthquake Warning Networks."""

GLOSSARY = {
    "threat model": "a structured description of what you defend against",
    "zero trust": "verifying every access request instead of trusting the network",
    "incident response": "the practiced plan for containing and recovering from events",
    "forensics": "reconstructing what happened from preserved evidence",
    "resilience": "the ability to keep essential functions running through disruption",
    "privacy-preserving": "achieving the goal while minimizing personal data exposure",
}

def lookup(term):
    key = term.strip().lower()
    for k, v in GLOSSARY.items():
        if k.lower() == key:
            return k + ": " + v
    cands = [k for k in GLOSSARY if key in k.lower()]
    return ("Did you mean: " + ", ".join(cands)) if cands else "No entry."


if __name__ == "__main__":
    print("Early Earthquake Warning Networks glossary — %d terms" % len(GLOSSARY))
    for t in list(GLOSSARY)[:3]:
        print("-", lookup(t))

"""Piece model: Sensor and Data Layer — part of the Early Earthquake Warning Networks system."""
import random

class EarlyEarthquakeWarningNetworksPiece1SensorAndDataLayer:
    """Models the Sensor and Data Layer piece: specification check and behavior sample."""

    SPEC = {"piece": "Sensor and Data Layer", "interfaces": 3, "redundancy": 2}

    def __init__(self, seed=11):
        self.rng = random.Random(seed)

    def spec_check(self):
        """Verify the piece meets its interface contract."""
        results = {}
        for i in range(self.SPEC["interfaces"]):
            # simulated conformance measurement around a nominal value
            measured = 1.0 + self.rng.uniform(-0.04, 0.04)
            results["interface_%d" % i] = round(measured, 3)
        ok = all(0.94 <= v <= 1.06 for v in results.values())
        return {"pass": ok, "measurements": results}

    def simulate(self, cycles=24):
        """Sample operating behavior over a number of cycles."""
        health = 1.0
        for _ in range(cycles):
            stress = self.rng.uniform(0.0, 0.06)
            health = max(0.0, health - stress * 0.2)
            health = min(1.0, health + 0.05)  # recovery / maintenance
        return {"cycles": cycles, "health": round(health, 3),
                "redundancy_ok": health > 0.5}


if __name__ == "__main__":
    m = EarlyEarthquakeWarningNetworksPiece1SensorAndDataLayer(seed=11)
    sc = m.spec_check()
    sm = m.simulate(24)
    print("Sensor and Data Layer — Early Earthquake Warning Networks")
    print("spec check pass:", sc["pass"], "| measurements:", sc["measurements"])
    print("health after", sm["cycles"], "cycles:", sm["health"])

